CREATE TABLE bookmark(idBookmark INTEGER PRIMARY KEY,idFile INTEGER,timeInSeconds DOUBLE,totalTimeInSeconds DOUBLE,type INTEGER); CREATE TABLE path(idPath INTEGER PRIMARY KEY,strPath TEXT,dateAdded TEXT); INSERT INTO path VALUES(2,'/tmp/tvshows/The.Big.Bang.Theory/','2013-10-23 18:58:43'); CREATE TABLE files(idFile INTEGER PRIMARY KEY,idPath INTEGER,strFilename TEXT,playCount INTEGER,lastPlayed TEXT,dateAdded TEXT); INSERT INTO files VALUES(1,2,'The.Big.Bang.Theory.S01E01.WEB-DL.AAC2.0.H264.mkv',NULL,NULL,'2013-10-23 18:57:36'); CREATE TABLE tvshow(idShow INTEGER PRIMARY KEY,c00 TEXT,c01 TEXT,c05 TEXT,c08 TEXT,c13 TEXT,c14 TEXT,c16 TEXT,c17 TEXT); INSERT INTO tvshow VALUES(1,'The Big Bang Theory','Leonard Hofstadter and Sheldon Cooper are brilliant physicists, the kind of "beautiful minds" that understand how the universe works. But none of that genius helps them interact with people, especially women. All this begins to change when a free-spirited beauty named Penny moves in next door. Sheldon, Leonard''s roommate, is quite content spending his nights playing Klingon Boggle with their socially dysfunctional friends, fellow CalTech scientists Howard Wolowitz and Raj Koothrappali. However, Leonard sees in Penny a whole new universe of possibilities... including love.','2007-09-24','Comedy','TV-PG','CBS','/tmp/tvshows/The.Big.Bang.Theory/','1'); CREATE TABLE episode(idEpisode INTEGER PRIMARY KEY,idFile INTEGER,c12 VARCHAR(24),c13 VARCHAR(24),c17 VARCHAR(24),c19 TEXT,idShow INTEGER); INSERT INTO episode VALUES(1,1,'1','1','-1','/tmp/tvshows/The.Big.Bang.Theory/The.Big.Bang.Theory.S01E01.WEB-DL.AAC2.0.H264.mkv',1); CREATE TABLE tvshowlinkpath(idShow INTEGER,idPath INTEGER); INSERT INTO tvshowlinkpath VALUES(1,2); CREATE TABLE seasons(idSeason INTEGER PRIMARY KEY,idShow INTEGER,season INTEGER); INSERT INTO seasons VALUES(1,1,-1),(2,1,0),(3,1,1),(4,1,2),(5,1,3),(6,1,4),(7,1,5),(8,1,6),(9,1,7); CREATE INDEX ix_bookmark ON bookmark(idFile,type); CREATE INDEX ix_path ON path(strPath); CREATE INDEX ix_files ON files(idPath,strFilename); CREATE UNIQUE INDEX ix_episode_file_1 ON episode(idEpisode,idFile); CREATE UNIQUE INDEX id_episode_file_2 ON episode(idFile,idEpisode); CREATE INDEX ix_episode_season_episode ON episode(c12,c13); CREATE INDEX ix_episode_bookmark ON episode(c17); CREATE INDEX ix_episode_show1 ON episode(idEpisode,idShow); CREATE INDEX ix_episode_show2 ON episode(idShow,idEpisode); CREATE UNIQUE INDEX ix_tvshowlinkpath_1 ON tvshowlinkpath(idShow,idPath); CREATE UNIQUE INDEX ix_tvshowlinkpath_2 ON tvshowlinkpath(idPath,idShow); CREATE INDEX ixEpisodeBasePath ON episode(c19); CREATE INDEX ixTVShowBasePath ON tvshow(c17); CREATE INDEX ix_seasons ON seasons(idShow,season); CREATE VIEW episodeview AS SELECT episode.*,files.strFilename AS strFileName,path.strPath AS strPath,files.playCount AS playCount,files.lastPlayed AS lastPlayed,files.dateAdded AS dateAdded,tvshow.c00 AS strTitle,tvshow.c14 AS strStudio,tvshow.c05 AS premiered,tvshow.c13 AS mpaa,tvshow.c16 AS strShowPath,bookmark.timeInSeconds AS resumeTimeInSeconds,bookmark.totalTimeInSeconds AS totalTimeInSeconds,seasons.idSeason AS idSeason FROM episode JOIN files ON files.idFile=episode.idFile JOIN tvshow ON tvshow.idShow=episode.idShow LEFT JOIN seasons ON seasons.idShow=episode.idShow AND seasons.season=episode.c12 JOIN path ON files.idPath=path.idPath LEFT JOIN bookmark ON bookmark.idFile=episode.idFile AND bookmark.type=1; CREATE VIEW tvshowview AS SELECT tvshow.*,path.strPath AS strPath,path.dateAdded AS dateAdded,Max(files.lastPlayed) AS lastPlayed,NULLIF(Count(episode.c12),0) AS totalCount,Count(files.playCount) AS watchedcount,NULLIF(Count(DISTINCT episode.c12),0) AS totalSeasons FROM tvshow LEFT JOIN tvshowlinkpath ON tvshowlinkpath.idShow=tvshow.idShow LEFT JOIN path ON path.idPath=tvshowlinkpath.idPath LEFT JOIN episode ON episode.idShow=tvshow.idShow LEFT JOIN files ON files.idFile=episode.idFile GROUP BY tvshow.idShow;